#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long MOD = 1000000007;
    int n;
    cin >> n;
    vector<int> p(n);
    for (auto &x : p) cin >> x;
    // The LCM of the cycle lengths, kept as the highest power of each prime it contains.
    vector<int> spf(n + 1, 0), best(n + 1, 0);
    for (int i = 2; i <= n; i++)
        if (!spf[i])
            for (int j = i; j <= n; j += i)
                if (!spf[j]) spf[j] = i;
    vector<char> seen(n, 0);
    for (int i = 0; i < n; i++) {
        if (seen[i]) continue;
        int len = 0;
        for (int j = i; !seen[j]; j = p[j] - 1) {
            seen[j] = 1;
            len++;
        }
        while (len > 1) {
            int pr = spf[len], e = 0;
            while (len % pr == 0) {
                len /= pr;
                e++;
            }
            if (e > best[pr]) best[pr] = e;
        }
    }
    long long ans = 1;
    for (int pr = 2; pr <= n; pr++)
        for (int e = 0; e < best[pr]; e++) ans = ans * pr % MOD;
    cout << ans << '\n';
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        final long MOD = 1_000_000_007L;
        int n = (int) nextLong();
        int[] p = new int[n];
        for (int i = 0; i < n; i++) p[i] = (int) nextLong() - 1;
        // The LCM of the cycle lengths, kept as the highest power of each prime it contains.
        int[] spf = new int[n + 1], best = new int[n + 1];
        for (int i = 2; i <= n; i++)
            if (spf[i] == 0)
                for (int j = i; j <= n; j += i)
                    if (spf[j] == 0) spf[j] = i;
        boolean[] seen = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            int len = 0;
            for (int j = i; !seen[j]; j = p[j]) {
                seen[j] = true;
                len++;
            }
            while (len > 1) {
                int pr = spf[len], e = 0;
                while (len % pr == 0) {
                    len /= pr;
                    e++;
                }
                best[pr] = Math.max(best[pr], e);
            }
        }
        long ans = 1;
        for (int pr = 2; pr <= n; pr++)
            for (int e = 0; e < best[pr]; e++) ans = ans * pr % MOD;
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	const mod = 1_000_000_007
	n := int(nextInt())
	p := make([]int, n)
	for i := range p {
		p[i] = int(nextInt()) - 1
	}
	// The LCM of the cycle lengths, kept as the highest power of each prime it contains.
	spf, best := make([]int, n+1), make([]int, n+1)
	for i := 2; i <= n; i++ {
		if spf[i] == 0 {
			for j := i; j <= n; j += i {
				if spf[j] == 0 {
					spf[j] = i
				}
			}
		}
	}
	seen := make([]bool, n)
	for i := 0; i < n; i++ {
		if seen[i] {
			continue
		}
		length := 0
		for j := i; !seen[j]; j = p[j] {
			seen[j] = true
			length++
		}
		for length > 1 {
			pr, e := spf[length], 0
			for length%pr == 0 {
				length /= pr
				e++
			}
			best[pr] = max(best[pr], e)
		}
	}
	ans := int64(1)
	for pr := 2; pr <= n; pr++ {
		for e := 0; e < best[pr]; e++ {
			ans = ans * int64(pr) % mod
		}
	}
	fmt.Println(ans)
}
